/**
 * Детерминированный шум: одно и то же число из одного и того же посева.
 *
 * Живёт в среде, а не в трассе, где лежало раньше, по простой причине: им
 * пользуются все, кому нужна воспроизводимая случайность в мире, — извилистость
 * дороги, профиль обочины, погода, расстановка деревьев. Пока хеш принадлежал
 * трассе, за ним туда ходили и небо, и лес, то есть трасса была общей
 * зависимостью просто потому, что в ней однажды написали семь строк арифметики.
 *
 * Это не генератор случайных чисел: состояния у него нет, и очередь вызовов ни
 * на что не влияет. Именно поэтому мир можно считать с середины — спросить, что
 * творится на километре двадцать, не пройдя первых девятнадцати.
 */
export function hash01(seed: number, index: number, salt: number): number {
  let h = (seed | 0) ^ 0x9e3779b9;
  h = Math.imul(h ^ (index | 0), 0x85ebca6b);
  h = Math.imul(h ^ (salt | 0), 0xc2b2ae35);
  h ^= h >>> 15;
  h = Math.imul(h, 0x2545f491);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

/** Сглаживание на отрезке: у краёв производная ноль, поэтому стыки не видны. */
export function smoothstep(t: number): number {
  return t * t * (3 - 2 * t);
}
